import { canonicalApplicationBytes, compileApplicationContract } from './canonical-application.js';
import { FLOW_PRIMITIVE_TYPES, diffFlowSpec, parseFlowSpec, planFlowSpecMigration, validateFlowSpec, } from './flowspec.js';
import { planModuleImplementation, resolveModuleIntent } from './module-intent.js';
import { collectApplicationUnderstanding } from './application-understanding.js';
async function sha256(value) {
    const digest = await crypto.subtle.digest('SHA-256', value.slice().buffer);
    return `sha256:${Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')}`;
}
export function createContractSnapshot(contract, options = {}) {
    const manifest = contract.manifest;
    // This is intentionally a whitelist. Metadata labels, environment
    // configuration, connections, and artifacts can contain deployment data and
    // must never become model context merely because the manifest grows.
    return {
        application: {
            application_id: contract.application_id,
            environment: options.environment ?? 'local',
        },
        contract_version: options.contractVersion ?? contract.schema_version,
        contract_hash: contract.hashes.application,
        dsl_version: contract.dsl_version,
        schema: manifest.collections,
        indexes: manifest.indexes,
        policies: manifest.policies,
        workflows: manifest.workflows,
        agents: manifest.agents,
        capabilities: manifest.capabilities,
        modules: manifest.modules ?? [],
        supported_primitives: FLOW_PRIMITIVE_TYPES,
    };
}
export function contractSnapshotText(snapshot) {
    return new TextDecoder().decode(canonicalApplicationBytes(snapshot));
}
/** Load the same whitelisted snapshot from local, self-hosted, or managed SDKs. */
export async function loadContractSnapshot(db) {
    const discovery = await db.application.get();
    const snapshot = discovery.snapshot;
    if (!snapshot || typeof snapshot.contract_hash !== 'string' || !Array.isArray(snapshot.schema)) {
        throw new Error('The application service did not return a FeltDB contract snapshot');
    }
    return snapshot;
}
export async function flowSourceHash(source) {
    return sha256(new TextEncoder().encode(source.replace(/\r\n/g, '\n')));
}
export const FELTDB_FLOW_DSL_GUIDE = `FeltDB FlowSpec v1 reference:
- One document: flow_version 1, then app Name { ... }.
- collection Name { field: primitive; optional fields append ?; references use ref Collection; indexes use index name using hash(field) }.
- capability Name { visibility public|internal|agent; read Collection; write Collection }.
- module Name { provider provider-name; version exact-semver }. Module-qualified references use ref module.Model.
- workflow Name { step step_name { read Collection | write Collection | capability CapabilityName } }.
- agent Name { capability CapabilityName; workflow WorkflowName }.
- policy Collection { read: expression; write: expression }. Preserve existing authorization unless the request explicitly requires a change.
- Valid policy examples include authenticated, member, owner, self(field), and alternatives joined with |.
- Every referenced collection, capability, and workflow must be declared. Names are case-sensitive.
- Use only supported_primitives from the supplied snapshot. Do not invent UI, deployment, record data, secrets, or executable implementation syntax.
- Make the smallest semantic change that satisfies the request and retain all unrelated declarations.`;
/** One provider-neutral prompt used by local WebLLM and bring-your-own models. */
export async function createFlowProposalMessages(snapshot, currentFlow, intent) {
    const resolvedIntent = resolveModuleIntent(intent);
    const understanding = await collectApplicationUnderstanding({ intent, snapshot, currentFlow, moduleIntent: resolvedIntent });
    const moduleIntent = resolvedIntent ? JSON.stringify(planModuleImplementation(resolvedIntent, snapshot, currentFlow, understanding)) : undefined;
    return [
        { role: 'system', content: [
                'You propose minimal changes to a FeltDB application.',
                'feltdb.flow is authoritative. Preserve every unrelated declaration verbatim in meaning.',
                `Generate flow_version ${snapshot.dsl_version} only. Never invent unsupported primitives.`,
                'Return only JSON with: proposedFlow, summary, changes, warnings.',
                'The proposedFlow value must contain the complete resulting document, not a patch or excerpt.',
                'Do not include application records, credentials, tokens, environment configuration, or deployment actions.',
                FELTDB_FLOW_DSL_GUIDE,
                `Current contract snapshot: ${contractSnapshotText(snapshot)}`,
                `Current feltdb.flow:\n${currentFlow}`,
                `Authoritative application understanding (evidence references, inferences, confidence, and unknowns; never promote an inference to an authoritative fact):\n${JSON.stringify(understanding)}`,
                moduleIntent ? `Authoritative resolved module implementation context (fit these semantics to the application; do not invent or redefine module semantics):\n${moduleIntent}` : '',
            ].join('\n\n') },
        { role: 'user', content: intent },
    ];
}
/** Parse and validate untrusted model output through the canonical FeltDB pipeline. */
export async function validateGeneratedFlowProposal(input) {
    const cleaned = input.raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    let value;
    try {
        value = JSON.parse(cleaned);
    }
    catch {
        throw new Error('The configured model returned an invalid flow proposal document');
    }
    const proposal = {
        baseContractHash: input.snapshot.contract_hash,
        baseFlowHash: await flowSourceHash(input.currentFlow),
        proposedFlow: String(value.proposedFlow ?? ''),
        summary: String(value.summary ?? ''),
        changes: Array.isArray(value.changes) ? value.changes.map(String) : [],
        warnings: Array.isArray(value.warnings) ? value.warnings.map(String) : [],
        understanding: await collectApplicationUnderstanding({ intent: input.intent, snapshot: input.snapshot, currentFlow: input.currentFlow, moduleIntent: resolveModuleIntent(input.intent) }),
    };
    const review = await validateFlowProposal({ proposal, currentFlow: input.currentFlow, snapshot: input.snapshot });
    if (!input.allowDestructiveProposal && (review.diff.removed.length || review.migration.some(item => item.safety === 'destructive'))) {
        throw new Error(`NON_MINIMAL_FLOW_PROPOSAL: generated change removes existing application semantics (${review.diff.removed.join(', ')})`);
    }
    return proposal;
}
function policyChanges(before, after) {
    const left = new Map(before.policies.map(policy => [policy.name, policy.statements]));
    const right = new Map(after.policies.map(policy => [policy.name, policy.statements]));
    const names = new Set([...left.keys(), ...right.keys()]);
    const broad = /\b(public|any|anonymous|authenticated)\b/i;
    return [...names].flatMap(policy => {
        const previous = left.get(policy);
        const next = right.get(policy);
        if (JSON.stringify(previous) === JSON.stringify(next))
            return [];
        const added = (next ?? []).filter(statement => !(previous ?? []).includes(statement));
        return [{ policy, before: previous, after: next, widening: !next || added.some(statement => broad.test(statement)) }];
    });
}
export async function validateFlowProposal(input) {
    const currentHash = await flowSourceHash(input.currentFlow);
    if (input.proposal.baseFlowHash !== currentHash) {
        throw new Error(`STALE_FLOW_PROPOSAL: proposal is based on ${input.proposal.baseFlowHash}, current flow is ${currentHash}`);
    }
    if (input.proposal.baseContractHash !== input.snapshot.contract_hash) {
        throw new Error(`STALE_CONTRACT_PROPOSAL: proposal is based on ${input.proposal.baseContractHash}, current contract is ${input.snapshot.contract_hash}`);
    }
    const current = parseFlowSpec(input.currentFlow);
    const proposedSpec = parseFlowSpec(input.proposal.proposedFlow);
    if (proposedSpec.version !== input.snapshot.dsl_version) {
        throw new Error(`DSL_VERSION_MISMATCH: proposal uses ${proposedSpec.version}, runtime requires ${input.snapshot.dsl_version}`);
    }
    const diagnostics = validateFlowSpec(proposedSpec);
    const errors = diagnostics.filter(item => item.severity === 'error');
    if (errors.length)
        throw new Error(`INVALID_FLOW_PROPOSAL: ${errors.map(item => item.message).join('; ')}`);
    const proposedContract = await compileApplicationContract(proposedSpec, input.tenantId ?? 'local', input.snapshot.application.application_id);
    return {
        proposal: input.proposal,
        proposedSpec,
        proposedContract,
        diagnostics,
        diff: diffFlowSpec(current, proposedSpec),
        migration: planFlowSpecMigration(current, proposedSpec),
        authorizationChanges: policyChanges(current, proposedSpec),
    };
}
